import numpy as np

class LSHMemoryCompressor:
    def __init__(self, dim, num_hashes):
        self.dim = dim
        self.num_hashes = num_hashes
        self.planes = np.random.randn(num_hashes, dim)

    def compute_hash(self, memory_vector):
